      "optional": true
    }
  },
  "engines": {
    "node": ">=22"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.3.2",
    "@opencode/theme": "^2.3.2",
    "@opentui/core": "^0.9.7",
    "@opentui/solid": "^0.9.7",
    "@types/node": "^26.6.6",
    "solid-js": "^1.9.20",
    "typescript": "^5.9.3"
  }
